package com.mutang.xunxi;

import java.util.*;
import org.json.*;

/** Merge subscriptions by URL and reading records by (source URL, article URL). */
final class SyncMerge {
    static final String FORMAT="xunji-sync-v1";
    static JSONArray arr(JSONObject o,String k){JSONArray a=o.optJSONArray(k);return a==null?new JSONArray():a;}
    static JSONObject obj(JSONObject o,String k){JSONObject a=o.optJSONObject(k);return a==null?new JSONObject():a;}
    static String clip(String s,int n){return s.length()>n?s.substring(0,n):s;}
    static JSONObject envelope(JSONObject state)throws JSONException{return new JSONObject().put("format",FORMAT).put("state",state).put("updatedAt",System.currentTimeMillis());}
    static JSONObject unpack(String text)throws Exception{JSONObject o=new JSONObject(text);if(!FORMAT.equals(o.optString("format"))||o.optJSONObject("state")==null)throw new IllegalArgumentException("云端文件格式不是讯集同步数据");JSONObject state=o.getJSONObject("state");if(state.optJSONArray("sources")==null||state.optJSONArray("posts")==null)throw new IllegalArgumentException("云端数据不完整");return state;}
    static JSONObject cleanSource(JSONObject s,String url,String id)throws JSONException{return new JSONObject().put("id",id).put("url",url).put("name",clip(s.optString("name",Collector.host(url)),80)).put("autoName",s.optBoolean("autoName",true)).put("checked",s.optLong("checked")).put("error",clip(s.optString("error"),300)).put("count",s.optInt("count")).put("initialized",s.optBoolean("initialized")).put("shortPostsInitialized",s.optBoolean("shortPostsInitialized")).put("addedAt",s.optLong("addedAt"));}
    static JSONObject cleanPost(JSONObject p,String id,String source,String name,String url)throws JSONException{return new JSONObject().put("id",id).put("source",source).put("sourceName",name).put("title",clip(p.optString("title"),260)).put("url",url).put("summary",clip(p.optString("summary"),400)).put("date",p.optLong("date")).put("found",p.optLong("found")).put("read",p.optBoolean("read")).put("shortPost",p.optBoolean("shortPost"));}
    static JSONObject merge(JSONObject local,JSONObject remote)throws Exception{
        JSONObject tombs=new JSONObject();for(JSONObject state:new JSONObject[]{local,remote}){JSONObject t=obj(state,"tombstones");for(Iterator<String> it=t.keys();it.hasNext();){String raw=it.next(),url=Collector.normalize(raw);if(url==null)continue;long at=t.optLong(raw);if(at>tombs.optLong(url))tombs.put(url,at);}}
        if(tombs.length()>3000)throw new IllegalArgumentException("同步删除记录过多，请检查云端数据");
        Map<String,JSONObject> chosen=new LinkedHashMap<>();Map<String,String> localIds=new HashMap<>(),remoteIds=new HashMap<>();Set<String> usedIds=new HashSet<>();
        for(int side=0;side<2;side++){JSONObject state=side==0?local:remote;Map<String,String> ids=side==0?localIds:remoteIds;JSONArray a=arr(state,"sources");if(a.length()>100)throw new IllegalArgumentException("云端订阅数量异常");for(int i=0;i<a.length();i++){JSONObject s=a.optJSONObject(i);if(s==null)continue;String url=Collector.normalize(s.optString("url")),oldId=s.optString("id");if(url==null||oldId.isEmpty()||(tombs.optLong(url)>0&&s.optLong("addedAt")<=tombs.optLong(url)))continue;ids.put(oldId,url);JSONObject existing=chosen.get(url);if(existing==null){String id=oldId;if(!id.matches("[A-Za-z0-9-]{1,80}")||!usedIds.add(id)){id=UUID.randomUUID().toString();usedIds.add(id);}chosen.put(url,cleanSource(s,url,id));}else{boolean newer=s.optLong("checked")>existing.optLong("checked");JSONObject n=newer?cleanSource(s,url,existing.optString("id")):existing;if(!existing.optBoolean("autoName")&&s.optBoolean("autoName")){n.put("name",existing.optString("name")).put("autoName",false);}else if(existing.optBoolean("autoName")&&!s.optBoolean("autoName")){n.put("name",clip(s.optString("name"),80)).put("autoName",false);}n.put("initialized",existing.optBoolean("initialized")||s.optBoolean("initialized"));n.put("shortPostsInitialized",existing.optBoolean("shortPostsInitialized")||s.optBoolean("shortPostsInitialized"));n.put("addedAt",Math.max(existing.optLong("addedAt"),s.optLong("addedAt")));chosen.put(url,n);}}}
        if(chosen.size()>30)throw new IllegalArgumentException("合并后超过30个订阅，请先清理订阅再同步");
        Map<String,JSONObject> posts=new LinkedHashMap<>();Set<String> postIds=new HashSet<>();Map<String,LinkedHashSet<String>> seen=new LinkedHashMap<>();
        for(int side=0;side<2;side++){JSONObject state=side==0?local:remote;Map<String,String> ids=side==0?localIds:remoteIds;JSONArray a=arr(state,"posts");if(a.length()>4000)throw new IllegalArgumentException("云端历史记录数量异常");for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null)continue;String src=ids.get(p.optString("source"));JSONObject s=chosen.get(src);if(s==null)continue;String u=Collector.normalize(Collector.repairPlaceholder(p.optString("url"),src));if(u==null)continue;String key=src+"\n"+u;String id=p.optString("id");JSONObject old=posts.get(key);if(old==null){if(!id.matches("[A-Za-z0-9-]{1,80}")||!postIds.add(id)){id=UUID.randomUUID().toString();postIds.add(id);}posts.put(key,cleanPost(p,id,s.optString("id"),s.optString("name"),u));}else{boolean read=old.optBoolean("read")||p.optBoolean("read");if(old.optString("summary").length()<p.optString("summary").length()||p.optLong("date")>old.optLong("date"))old=cleanPost(p,old.optString("id"),s.optString("id"),s.optString("name"),u);old.put("read",read);posts.put(key,old);}seen.computeIfAbsent(s.optString("id"),k->new LinkedHashSet<>()).add(u);}
            JSONObject history=obj(state,"seen");for(String oldId:ids.keySet()){String src=ids.get(oldId);JSONObject s=chosen.get(src);JSONArray h=history.optJSONArray(oldId);if(s==null||h==null)continue;LinkedHashSet<String> set=seen.computeIfAbsent(s.optString("id"),k->new LinkedHashSet<>());for(int j=Math.max(0,h.length()-3000);j<h.length();j++){String u=Collector.normalize(Collector.repairPlaceholder(h.optString(j),src));if(u!=null)set.add(u);}}}
        ArrayList<JSONObject> sorted=new ArrayList<>(posts.values());sorted.sort((a,b)->Long.compare(Math.max(b.optLong("date"),b.optLong("found")),Math.max(a.optLong("date"),a.optLong("found"))));if(sorted.size()>1600)sorted=new ArrayList<>(sorted.subList(0,1600));JSONObject histories=new JSONObject();for(Map.Entry<String,LinkedHashSet<String>> e:seen.entrySet()){ArrayList<String> a=new ArrayList<>(e.getValue());histories.put(e.getKey(),new JSONArray(a.subList(Math.max(0,a.size()-3000),a.size())));}
        return new JSONObject().put("sources",new JSONArray(chosen.values())).put("posts",new JSONArray(sorted)).put("seen",histories).put("tombstones",tombs);
    }
}
